() => {
  const out = [];
  document.querySelectorAll('#flyer > *').forEach(el => {
    const r = el.getBoundingClientRect();
    out.push(`${el.className||el.tagName}: y=${r.top.toFixed(1)}-${r.bottom.toFixed(1)} x=${r.left.toFixed(1)}-${r.right.toFixed(1)}`);
  });
  const f = document.getElementById('flyer');
  out.push(`scrollH=${f.scrollHeight} clientH=${f.clientHeight} scrollW=${f.scrollWidth}`);
  document.querySelectorAll('.nm,.rl,.cta span,.step span,.foot,h1').forEach(el=>{
    if (el.scrollWidth > el.clientWidth+0.5) out.push('OVERFLOW-X: '+el.textContent);
  });
  return out.join('\n');
}

